import React, { useEffect, useState } from 'react';
import { Download, Lock } from 'lucide-react';
import { downloadResearchExport, getResearchSummary } from '../api/dashboard';
import type { ResearchSummary } from '../types';
import { Card, Empty, ErrorNote, Metric, ui } from './ui';

/** De-identified exports generated by the server (researcher and admin roles only). */
export const ResearchView: React.FC = () => {
  const [summary, setSummary] = useState<ResearchSummary | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [lang, setLang] = useState('');
  const [busy, setBusy] = useState<string | null>(null);
  const [last, setLast] = useState<string | null>(null);

  useEffect(() => {
    getResearchSummary()
      .then(setSummary)
      .catch((e: unknown) => setErr(e instanceof Error ? e.message : 'Could not load summary'));
  }, []);

  const run = async (dataset: 'reading' | 'writing' | 'participants') => {
    setBusy(dataset);
    setErr(null);
    try {
      const r = await downloadResearchExport(dataset, lang || undefined);
      setLast(`${dataset}.csv downloaded · SHA-256 ${r.sha256.slice(0, 16)}… (recorded in the export log)`);
    } catch (e: unknown) {
      setErr(e instanceof Error ? e.message : 'Export failed');
    } finally {
      setBusy(null);
    }
  };

  return (
    <div style={ui.page} className="fade-in">
      <Card>
        <div style={{ display: 'flex', gap: '0.8rem', alignItems: 'flex-start' }}>
          <Lock size={20} color="var(--color-deep-forest)" />
          <p style={{ fontSize: '0.88rem', color: 'var(--color-slate-700)', lineHeight: 1.55 }}>
            Exports include only participants whose most recent consent record is active with research consent. Rows are keyed by Participant ID; names,
            e-mail addresses, guardian names and school names are never included. Every export is logged with who ran it and a checksum of the file.
          </p>
        </div>
      </Card>
      {err && <ErrorNote>{err}</ErrorNote>}
      {!summary ? (
        <Card>
          <Empty>Loading…</Empty>
        </Card>
      ) : (
        <div style={ui.metrics}>
          <Metric label="Consented participants" value={summary.consentedParticipants} />
          <Metric label="Reading attempts" value={summary.readingAttempts} hint={`${summary.readingWithAudio} with original audio`} />
          <Metric label="Writing attempts" value={summary.writingAttempts} hint={`${summary.writingFromImage} handwritten`} />
          <Metric label="English / Kannada reading" value={`${summary.byLanguage.English.reading} / ${summary.byLanguage.Kannada.reading}`} />
          <Metric
            label="Metrics not verified"
            value={summary.readingMetricsUnverified}
            hint="Server recalculation disagreed with the phone"
            tone={summary.readingMetricsUnverified ? 'risk' : 'normal'}
          />
        </div>
      )}
      <Card title="Download CSV" sub="UTF-8 with BOM so Kannada text opens correctly in spreadsheet software">
        <div style={ui.filters}>
          <select style={ui.input} value={lang} onChange={(e) => setLang(e.target.value)} aria-label="Language filter">
            <option value="">All languages</option>
            <option>English</option>
            <option>Kannada</option>
          </select>
          {(['reading', 'writing', 'participants'] as const).map((d) => (
            <button key={d} style={ui.primaryBtn} disabled={!!busy} onClick={() => run(d)}>
              <Download size={14} /> {busy === d ? 'Preparing…' : `${d[0].toUpperCase()}${d.slice(1)} dataset`}
            </button>
          ))}
        </div>
        {last && <p style={{ ...ui.muted, marginTop: '0.7rem' }}>{last}</p>}
      </Card>
    </div>
  );
};
